<script>export let result;const number=v=>v==null?'—':Number(v).toLocaleString(undefined,{maximumFractionDigits:1});</script>
{#if result?.rows?.length}<section class="connector-results"><h2>Connectors</h2><div class="table-wrap"><table><thead><tr><th>Connector</th><th>Assigned flows</th><th>Target / routed</th><th>Reported confirmations</th><th>Succeeded</th><th>Failed</th><th>HS-only p99</th><th>Full confirm p99</th></tr></thead><tbody>{#each result.rows as row}<tr><td>{row.connector}</td><td>{number(row.assigned)}</td><td>{number(row.targetPercent)}% / {number(row.observedPercent)}%</td><td>{number(row.confirmations)}</td><td>{number(row.successes)}</td><td>{number(row.failures)}</td><td>{number(row.hsP99)} ms</td><td>{number(row.fullP99)} ms</td></tr>{/each}</tbody></table></div>{#if result.unattributedConfirmations}<p>{number(result.unattributedConfirmations)} confirmation responses did not report a connector.</p>{/if}</section>{/if}
<style>.connector-results{margin:24px 0;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:20px}.connector-results h2{margin-bottom:16px}.connector-results p{font-size:12px;color:var(--muted)}</style>
